using V=std::vector<uint8_t>;
void put16(V& v,size_t at,uint16_t n){v[at]=n&255;v[at+1]=n>>8;}void put32(V& v,size_t at,uint32_t n){for(int i=0;i<4;i++)v[at+i]=uint8_t(n>>(i*8));}
V usb(V body,int endpoint,int type,int complete=1,int device=7){V packet(27);put16(packet,0,27);packet[16]=complete;put16(packet,19,device);packet[21]=endpoint;packet[22]=type;put32(packet,23,uint32_t(body.size()));packet.insert(packet.end(),body.begin(),body.end());V record(16);put32(record,0,10);put32(record,8,uint32_t(packet.size()));put32(record,12,uint32_t(packet.size()));record.insert(record.end(),packet.begin(),packet.end());return record;}
V acl(V body,bool in,uint16_t cid=1,uint16_t handle=0x200){V l2(8);put16(l2,0,handle|0x2000);put16(l2,2,uint16_t(body.size()+4));put16(l2,4,uint16_t(body.size()));put16(l2,6,cid);l2.insert(l2.end(),body.begin(),body.end());return usb(l2,in?0x82:2,3,in?1:0);}
V fileHeader(){V v(24);put32(v,0,0xa1b2c3d4);put16(v,4,2);put16(v,6,4);put32(v,16,256);put32(v,20,249);return v;}
void check(bool v){if(!v)throw std::runtime_error("Failed");}
int main(){unsigned reports=0;MouseUsb::Parser p(0x102030405060ULL,7,[&](const uint8_t* b,size_t n,double){check(b[0]==0x12&&n==22);reports++;});auto feed=[&](V v){for(size_t at=0;at<v.size();){size_t n=std::min<size_t>(3,v.size()-at);check(p.Feed(v.data()+at,n));at+=n;}};feed(fileHeader());V touch(23);touch[0]=0xa1;touch[1]=0x12;
feed(acl(touch,true,0x40));check(!reports);feed(usb({3,11,0,0,2,0x60,0x50,0x40,0x30,0x20,0x10,1,1},0x81,1));check(p.counts.connections==1&&!p.Bound());feed(acl({2,1,4,0,0x13,0,0x40,0},false));feed(acl({3,1,8,0,0x41,0,0x40,0,0,0,0,0},true));check(p.Bound());feed(acl(touch,true,0x40));check(reports==1);feed(acl(touch,true,0x40,0x201));check(reports==1);feed(usb({5,4,0,0,2,0x13},0x81,1));feed(acl(touch,true,0x40));check(reports==1&&!p.Bound());V bad=fileHeader();bad[0]=0;MouseUsb::Parser broken(1,7);check(!broken.Feed(bad.data(),bad.size()));
// Unrelated USB addresses, malformed framing and absent address-bound handshake
// must never produce a mouse callback.
MouseUsb::Parser fuzz(0x102030405060ULL,7,[&](const uint8_t*,size_t,double){throw std::runtime_error("Unbound callback");});auto h=fileHeader();check(fuzz.Feed(h.data(),h.size()));uint32_t rng=12345;for(int k=0;k<10000;k++){V noise(1+(k%180));for(auto& b:noise){rng=rng*1664525+1013904223;b=rng>>24;}auto r=usb(noise,0x82,3,1,k%2?8:7);check(fuzz.Feed(r.data(),r.size()));}
std::array<uint8_t,16> nonce{};for(unsigned i=0;i<16;i++)nonce[i]=uint8_t(i+1);unsigned provedReports=0;MouseUsb::Parser proof(0x102030405060ULL,7,[&](const uint8_t*,size_t,double){provedReports++;});proof.SetProof(nonce);auto ph=fileHeader();check(proof.Feed(ph.data(),ph.size()));V request={2,0,1,0,22,0x35,17,0x1c};request.insert(request.end(),nonce.begin(),nonce.end());request.insert(request.end(),{0xff,0xff,0});auto query=acl(request,false,0x50);check(proof.Feed(query.data(),query.size()));check(proof.counts.proofBindings==1);auto report=acl(touch,true,0x40);check(proof.Feed(report.data(),report.size()));check(provedReports==1&&proof.Bound());auto other=acl(touch,true,0x40,0x201);check(proof.Feed(other.data(),other.size()));check(provedReports==1);
for(unsigned boundary:{0u,2u}){unsigned matched=0;MouseUsb::Parser candidate(0x102030405060ULL,7,[&](const uint8_t*,size_t,double){matched++;});candidate.SetProof(nonce);check(candidate.Feed(ph.data(),ph.size()));auto q=acl(request,false,0x50);put16(q,16+27,0x200|(boundary<<12));check(candidate.Feed(q.data(),q.size()));check(candidate.counts.proofBindings==1);check(candidate.Feed(report.data(),report.size()));check(matched==1);}
{unsigned matched=0;MouseUsb::Parser pending(0x102030405060ULL,7,[&](const uint8_t*,size_t,double){matched++;});pending.SetProof(nonce);check(pending.Feed(ph.data(),ph.size()));auto q=acl(request,false,0x50);put16(q,16+27,0x200);put32(q,16+10,0x40000000);check(pending.Feed(q.data(),q.size()));check(pending.counts.pendingSubmits==1&&pending.counts.proofBindings==1);check(pending.Feed(report.data(),report.size()));check(matched==1);}
puts("PASS MAC-bound HCI/L2CAP handshake, split PCAP records, exact USB device, report bounds, disconnect reset SDP nonce binding and 10000 malformed/unrelated packets");}
